var DATA_GATES=[{"code":"DQ-01","name":"组织编码完整性","trigger":"统一社会信用代码缺失或重复","action":"提示补齐组织编码后重试"},{"code":"DQ-02","name":"外键关联完整性","trigger":"合同、招采、履约、资金、发票、流程关键 ID 无法关联","action":"标记暂无法判断，补齐关联字段后重试"},{"code":"DQ-03","name":"时间完整性","trigger":"决策、审批、签约、履约、结算、支付关键时间缺失","action":"提示补齐关键时间，暂不进入模型判断"},{"code":"DQ-04","name":"金额一致性","trigger":"合同、招采、中标、结算、发票、支付金额不一致","action":"提示核对金额口径后重试"},{"code":"DQ-05","name":"主数据一致性","trigger":"客商名称、信用代码、银行账号不一致","action":"提示统一主数据后重试"},{"code":"DQ-06","name":"接口时效性","trigger":"未按频率上传或接口连续失败","action":"提示接口恢复后重试"}];
